import { neon } from '@neondatabase/serverless'

export interface UpsertContactInput {
  email: string
  firstName?: string | null
  lastName?: string | null
  phone?: string | null
  source: string
  teamSlug?: string | null
  tags?: string[]
  /**
   * The TCPA consent record from the lead this contact came from, if any.
   *
   * Passed through rather than recomputed: the timestamp was generated by the
   * server at the moment of the tick, and re-stamping it here would date the
   * evidence to the merge instead of to the consent. Callers with no consent to
   * carry (CSV import, an unticked submission) simply omit it — a bulk import
   * is not consent, and nothing here will invent one.
   */
  consentAt?: string | null
  consentPhone?: string | null
}

export interface NormalizedContactInput {
  email: string
  firstName: string | null
  lastName: string | null
  phone: string | null
  source: string
  teamSlug: string | null
  tags: string[]
  consentAt: string | null
  consentPhone: string | null
}

export function normalizeContactInput(input: UpsertContactInput): NormalizedContactInput {
  const phone = input.phone?.trim() || null
  const consentPhone = input.consentPhone?.trim() || null

  // A consent pair is only carried when it names the number actually being
  // stored. Consent attaches to the NUMBER, so a pair that names anything else
  // is not evidence for this contact and is dropped rather than written — a
  // half-record here would read as consent for whatever phone the row ends up
  // holding, which is the entire failure this pair exists to prevent.
  const pairIsForThisPhone =
    !!input.consentAt && !!consentPhone && !!phone && consentPhone === phone

  return {
    email: input.email.trim().toLowerCase(),
    firstName: input.firstName?.trim() || null,
    lastName: input.lastName?.trim() || null,
    phone,
    source: input.source.trim(),
    teamSlug: input.teamSlug?.trim() || null,
    tags: Array.from(new Set((input.tags ?? []).map((t) => t.trim()).filter(Boolean))),
    consentAt: pairIsForThisPhone ? input.consentAt! : null,
    consentPhone: pairIsForThisPhone ? consentPhone : null,
  }
}

function getSql() {
  const url = process.env.DATABASE_URL
  if (!url) return null
  return neon(url)
}

// Insert-or-merge by email. Never blanks out better data already on file
// (COALESCE on name/phone), and merges sources/tags as a deduped array
// union entirely in SQL so concurrent upserts stay race-free.
export async function upsertContact(input: UpsertContactInput): Promise<void> {
  const sql = getSql()
  if (!sql) return
  const n = normalizeContactInput(input)
  if (!n.email) return

  await sql`
    INSERT INTO contacts (email, first_name, last_name, phone, sources, team_slug, tags, consent_at, consent_phone)
    VALUES (${n.email}, ${n.firstName}, ${n.lastName}, ${n.phone}, ${JSON.stringify([n.source])}::jsonb, ${n.teamSlug}, ${JSON.stringify(n.tags)}::jsonb, ${n.consentAt}, ${n.consentPhone})
    ON CONFLICT (email) DO UPDATE SET
      first_name = COALESCE(EXCLUDED.first_name, contacts.first_name),
      last_name  = COALESCE(EXCLUDED.last_name, contacts.last_name),
      phone      = COALESCE(EXCLUDED.phone, contacts.phone),
      sources    = (SELECT jsonb_agg(DISTINCT v) FROM jsonb_array_elements_text(contacts.sources || EXCLUDED.sources) v),
      team_slug  = COALESCE(EXCLUDED.team_slug, contacts.team_slug),
      tags       = (SELECT jsonb_agg(DISTINCT v) FROM jsonb_array_elements_text(contacts.tags || EXCLUDED.tags) v),
      -- The pair moves together or not at all, keyed on the timestamp. Column-wise
      -- COALESCE could pair a fresh timestamp with a stale number, which is the one
      -- combination that would assert consent for a number nobody ticked for.
      consent_at    = CASE WHEN EXCLUDED.consent_at IS NOT NULL THEN EXCLUDED.consent_at    ELSE contacts.consent_at    END,
      consent_phone = CASE WHEN EXCLUDED.consent_at IS NOT NULL THEN EXCLUDED.consent_phone ELSE contacts.consent_phone END,
      updated_at = now()
  `
  // Note on the interaction with the phone merge above: an incoming row with no
  // consent still replaces a non-null phone, which can leave the retained pair
  // naming a number this contact no longer has. That is deliberate and safe —
  // every read compares consent_phone against the current phone, so the row
  // simply stops reading as consented. Blanking the pair here instead would
  // destroy the record of a consent that was genuinely given, which is the one
  // thing that cannot be recreated.
}
